const payload = $json.body ?? $json;

if (!payload || typeof payload !== 'object') {
  return [
    {
      json: {
        status: 'FAILED',
        message: 'Invalid request payload.',
        metadata: {
          executor: 'n8n',
          validation: true,
          stage: 'payload_validation'
        }
      }
    }
  ];
}

const required = [
  'job_id',
  'title',
  'company',
  'location',
  'job_url',
  'queue_status'
];

const missing = required.filter((field) => {
  const value = payload[field];
  return value === undefined || value === null || String(value).trim() === '';
});

if (missing.length > 0) {
  return [
    {
      json: {
        status: 'FAILED',
        message: `Missing required fields: ${missing.join(', ')}`,
        metadata: {
          executor: 'n8n',
          validation: true,
          stage: 'payload_validation',
          missing_fields: missing
        }
      }
    }
  ];
}

const executableStatuses = [
  'READY',
  'READY_WITH_TAILORING'
];

const queueStatus = String(payload.queue_status).trim().toUpperCase();

if (!executableStatuses.includes(queueStatus)) {
  return [
    {
      json: {
        status: 'REJECTED',
        message: `Queue item is not executable: ${queueStatus}`,
        metadata: {
          executor: 'n8n',
          validation: true,
          stage: 'queue_validation',
          queue_status: queueStatus,
          external_submission: false
        }
      }
    }
  ];
}

return [
  {
    json: {
      ...payload,
      _n8n_validation: {
        payload_valid: true,
        queue_status_valid: true,
        external_submission: false
      }
    }
  }
];

const payload = $json;

if (payload.status === 'FAILED' || payload.status === 'REJECTED') {
  return [
    {
      json: payload
    }
  ];
}

const queueStatus = String(payload.queue_status).trim().toUpperCase();
const tailoringRequired = queueStatus === 'READY_WITH_TAILORING';

return [
  {
    json: {
      status: 'READY',
      message: tailoringRequired
        ? 'Application accepted by n8n boundary; resume tailoring is required before submission.'
        : 'Application accepted by n8n boundary; external submission is disabled in Stage 2.',
      metadata: {
        executor: 'n8n-local-stage-2',
        validation: true,
        external_submission: false,
        application_ready: true,
        resume_tailoring_required: tailoringRequired,
        queue_status: queueStatus,
        job_id: payload.job_id,
        company: payload.company,
        title: payload.title
      }
    }
  }
];
